<?php
namespace App\Http\Resources;use Illuminate\Http\Request;use Illuminate\Http\Resources\Json\JsonResource;
class FleetDeviceResource extends JsonResource { public function toArray(Request $request):array{$admin=$request->user()->isPlatformAdmin();$assignment=$admin?null:$this->accessAssignments->first();return ['id'=>(string)$this->id,'name'=>$this->name,'identifier'=>$this->external_id,'status'=>$this->status,'type'=>$this->type,'protocol'=>$this->protocol,'lastSeen'=>$this->last_seen?->toISOString(),'template'=>$this->template?['id'=>(string)$this->template->id,'name'=>$this->template->name]:null,'location'=>$this->canonicalLocation?['id'=>(string)$this->canonicalLocation->id,'name'=>$this->canonicalLocation->name]:null,'access'=>['level'=>$assignment?->access_level,'label'=>$admin?'Admin':($assignment?->access_level==='full_access'?'Full Access':'Viewer'),'canManage'=>$admin||$assignment?->access_level==='full_access']];}}
